                                      Offset end_offset,
                                      Opcode* final_opcode) {
  while (state_.offset < end_offset) {
    Opcode opcode;
    CHECK_RESULT(ReadOpcode(&opcode, "opcode"));
    CALLBACK(OnOpcode, opcode);
    ERROR_UNLESS_OPCODE_ENABLED(opcode);
    if (final_opcode) {
      *final_opcode = opcode;
    }

